  asOfDate: "2026-05-31",
  instruments: [
    indenture("deb-11", "escritura_11a_emissao.pdf", "4.22.3(j)", 34, ["cra-eco-8"], ["EBITDA dos últimos doze meses de sociedade adquirida nos doze meses anteriores e sellers finance"]),
