    "lint": "tsc -p tsconfig.json --noEmit",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run --exclude 'dist/**'"
  },
  "dependencies": {
    "@offroad/credit-ontology": "workspace:*",
    "@offroad/financial-core": "workspace:*",
    "@offroad/work-plan": "workspace:*",
