     1	import {createHash} from "node:crypto";
     2	
     3	import Decimal from "decimal.js";
     4	import {z} from "zod";
     5	
     6	/**
     7	 * Executor of the method `reconcile-covenant-definitions`. It never writes "breached": it
     8	 * resolves which tier applies from dated facts, decides comparability by comparing the
     9	 * components of the definitions (never by a caller's flag), and only then measures headroom.
    10	 * An unproven condition leaves the limit unresolved and the item conditioned, with the reason.
    11	 * A trustee report without the indenture yields a reported limit and no headroom. Every number
    12	 * it produces carries its operands in the trace.
    13	 */
    14	const ratio = z.string().regex(/^\d+(\.\d+)?$/);
    15	const money = z.string().regex(/^-?\d+(\.\d+)?$/);
    16	const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
    17	const indentureAnchorSchema = z.object({document: z.string().min(1), clause: z.string().min(1), page: z.number().int().positive()}).strict();
    18	const anchorSchema = z.object({document: z.string().min(1), clause: z.string().optional(), page: z.number().int().positive().optional(), note: z.string().optional()}).strict();
    19	type Anchor = z.infer<typeof anchorSchema>;
    20	
    21	/** The components a net debt definition is built from; comparability is decided on these, not on prose. */
    22	export const netDebtComponentSchema = z.enum([
    23	  "loans_and_financings", "debentures", "derivative_liabilities", "other_onerous_debt", "leases",
    24	  "cash_and_equivalents", "financial_investments", "derivative_assets",
    25	]);
    26	
    27	export const covenantTierSchema = z.object({
    28	  limit: ratio,
    29	  condition: z.discriminatedUnion("type", [
    30	    z.object({type: z.literal("unconditional")}).strict(),
    31	    z.object({type: z.literal("until_reference_settled"), referenceInstruments: z.array(z.string().min(1)).min(1)}).strict(),
    32	    z.object({type: z.literal("after_reference_settled"), referenceInstruments: z.array(z.string().min(1)).min(1)}).strict(),
    33	  ]),
    34	}).strict();
    35	
    36	export const covenantInstrumentSchema = z.discriminatedUnion("source", [
    37	  z.object({
    38	    source: z.literal("indenture"),
    39	    id: z.string().min(1),
    40	    indexName: z.string().min(1),
    41	    direction: z.enum(["maximum", "minimum"]).default("maximum"),
    42	    netDebtDefinition: z.string().min(1),
    43	    netDebtComponents: z.array(netDebtComponentSchema).min(1),
    44	    ebitdaDefinition: z.string().min(1),
    45	    /** Adjustments beyond the base definition (acquisition pro forma, sellers finance, ...). */
    46	    ebitdaAdjustments: z.array(z.string().min(1)).default([]),
    47	    measurement: z.object({frequency: z.enum(["annual", "semiannual", "quarterly"]), basis: z.string().min(1), fiscalYearEnd: z.string().regex(/^\d{2}-\d{2}$/)}).strict(),
    48	    tiers: z.array(covenantTierSchema).min(1),
    49	    anchor: indentureAnchorSchema,
    50	  }).strict(),
    51	  z.object({
    52	    source: z.literal("trustee_report"),
    53	    id: z.string().min(1),
    54	    indexName: z.string().min(1),
    55	    reportedLimit: ratio,
    56	    reportedMeasurement: z.object({value: ratio, asOf: isoDate}).strict().nullable().default(null),
    57	    anchor: anchorSchema,
    58	  }).strict(),
    59	]);
    60	
    61	export const covenantReconciliationInputSchema = z.object({
    62	  asOfDate: isoDate,
    63	  instruments: z.array(covenantInstrumentSchema),
    64	  referenceSettlements: z.array(z.object({
    65	    instrument: z.string().min(1),
    66	    maturityDate: isoDate,
    67	    /** ordinary: settled in the ordinary course (at maturity or early); accelerated: settled by acceleration; outstanding: still alive; unknown: the base does not say. */
    68	    settlement: z.enum(["ordinary", "accelerated", "outstanding", "unknown"]),
    69	    settlementDate: isoDate.nullable().default(null),
    70	    anchor: anchorSchema,
    71	  }).strict()).default([]),
    72	  /** Financial components at the as-of date, from the ledger; the executor computes net debt from them. */
    73	  components: z.object({
    74	    grossDebt: money, derivativeLiabilities: money, derivativeAssets: money, cashAndEquivalents: money, financialInvestments: money,
    75	    anchors: z.object({debt: anchorSchema, cash: anchorSchema, derivatives: anchorSchema}).strict(),
    76	  }).strict().nullable().default(null),
    77	  /** LTM EBITDA as the company computes it for the covenant, when it is opened; null otherwise. */
    78	  ltmEbitda: z.object({value: money, anchor: anchorSchema}).strict().nullable().default(null),
    79	  reported: z.object({
